SELECT CAST(COUNT(DISTINCT CASE WHEN p.anchor_age BETWEEN 83 AND 93 AND p.gender = 'F' AND d.icd_code IN ('250.0', '250.1') AND e.infusion_type IN ('basal', 'bolus', 'basal-bolus', 'sliding-scale') AND e.charttime BETWEEN a.intime AND a.intime + INTERVAL '48 hours' THEN e.emar_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.emar_id), 0) AS proportion_first_48h, CAST(COUNT(DISTINCT CASE WHEN p.anchor_age BETWEEN 83 AND 93 AND p.gender = 'F' AND d.icd_code IN ('250.0', '250.1') AND e.infusion_type IN ('basal', 'bolus', 'basal-bolus', 'sliding-scale') AND e.charttime BETWEEN a.intime + INTERVAL '48 hours' AND a.intime + INTERVAL '12 hours' THEN e.emar_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.emar_id), 0) AS proportion_final_12h, CAST(COUNT(DISTINCT CASE WHEN p.anchor_age BETWEEN 83 AND 93 AND p.gender = 'F' AND d.icd_code IN ('250.0', '250.1') AND e.infusion_type IN ('basal', 'bolus', 'basal-bolus', 'sliding-scale') AND e.charttime BETWEEN a.intime AND a.intime + INTERVAL '12 hours' THEN e.emar_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.emar_id), 0) AS proportion_net_change FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN emar e ON a.subject_id = e.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE a.subject_id = 757071;